CREATE TABLE IF NOT EXISTS tap_room_profiles (user_id INTEGER PRIMARY KEY, display_name TEXT NOT NULL, bio TEXT, joined_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, treatment_rules_ack_at TEXT, privacy_prompt_seen_at TEXT, status TEXT NOT NULL DEFAULT 'active', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tap_room_posts (id INTEGER PRIMARY KEY AUTOINCREMENT, room_slug TEXT NOT NULL, user_id INTEGER, parent_id INTEGER, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'visible', is_founder_prompt INTEGER NOT NULL DEFAULT 0, risk_flags_json TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TEXT, deleted_by INTEGER);
CREATE TABLE IF NOT EXISTS tap_room_blocks (blocker_user_id INTEGER NOT NULL, blocked_user_id INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(blocker_user_id,blocked_user_id));
CREATE TABLE IF NOT EXISTS tap_room_reports (id INTEGER PRIMARY KEY AUTOINCREMENT, reporter_user_id INTEGER NOT NULL, post_id INTEGER NOT NULL, category TEXT NOT NULL, detail TEXT, priority TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_at TEXT, reviewed_by TEXT, outcome TEXT);
CREATE TABLE IF NOT EXISTS tap_room_moderation_audit (id INTEGER PRIMARY KEY AUTOINCREMENT, actor TEXT NOT NULL, action TEXT NOT NULL, reason TEXT NOT NULL, content_id INTEGER, affected_user_id INTEGER, metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tap_room_restrictions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, restriction_type TEXT NOT NULL, starts_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, ends_at TEXT, reason TEXT NOT NULL, created_by TEXT NOT NULL, revoked_at TEXT);
CREATE TABLE IF NOT EXISTS tap_room_events (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, event_name TEXT NOT NULL, room_slug TEXT, post_id INTEGER, metadata_json TEXT NOT NULL DEFAULT '{}', occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tap_room_erasure_requests (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'received', requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, due_at TEXT NOT NULL, completed_at TEXT, UNIQUE(user_id,status));
CREATE TABLE IF NOT EXISTS tap_room_appeals (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,restriction_id INTEGER,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_at TEXT,reviewed_by TEXT,decision TEXT);
CREATE TABLE IF NOT EXISTS tap_room_hosts (user_id INTEGER PRIMARY KEY,invited_by TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'invited',invited_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,accepted_at TEXT);
CREATE INDEX IF NOT EXISTS idx_tap_posts_room_created ON tap_room_posts(room_slug,status,created_at);
CREATE INDEX IF NOT EXISTS idx_tap_posts_parent ON tap_room_posts(parent_id,status,created_at);
CREATE INDEX IF NOT EXISTS idx_tap_reports_status ON tap_room_reports(status,priority,created_at);
CREATE INDEX IF NOT EXISTS idx_tap_events_name_time ON tap_room_events(event_name,occurred_at);
CREATE INDEX IF NOT EXISTS idx_tap_moderation_time ON tap_room_moderation_audit(created_at);
